import { useEffect, useRef, useState } from 'react'

// Faisal's developer console (claude-session), mounted as built. The page is generated by claude-session/src/build_platform.py
// and loaded only here, after the admin sign-in guard, so it is not part of the public pages. It starts already signed in as the
// developer user; leaving it (its own logout or its link to the site) sends a message that returns to the admin.
export default function FaisalPlatform({ onExit }: { onExit: () => void }) {
  const [doc, setDoc] = useState<string | null>(null)
  const frame = useRef<HTMLIFrameElement>(null)

  useEffect(() => { void import('../../../faisal/platformDoc').then(m => setDoc(m.default)) }, [])
  useEffect(() => {
    const onMsg = (e: MessageEvent) => {
      if (e.source === frame.current?.contentWindow && e.data && e.data.madar === 'faisal-exit') onExit()
    }
    window.addEventListener('message', onMsg)
    return () => window.removeEventListener('message', onMsg)
  }, [onExit])

  if (!doc) return <div className="mc-faisal-load">جارٍ التحميل...</div>
  return <iframe ref={frame} className="mc-faisal-frame" title="لوحة فيصل" srcDoc={doc} />
}
